T={(0,2),(1,0),(1,1),(2,0),(2,1),(3,0)}
# 8 sym, normalize
import numpy as np
variants=[]
for flip in [False,True]:
 s=T
 if flip: s={(r,-c) for r,c in s}
 for k in range(4):
  pts=list(s)
  mr=min(r for r,c in pts); mc=min(c for r,c in pts)
  n=frozenset((r-mr,c-mc) for r,c in pts)
  if n not in variants: variants.append(n)
  s={(c,-r) for r,c in s}
print(variants)
G={(0,1),(0,2),(1,0),(1,1),(1,2),(2,0),(2,1),(3,0)}
for v in variants:
 for r in range(4):
  for c in range(4):
   sh={(y+r,x+c) for y,x in v}
   if sh<=G: print('fit',r,c,v)

